const (
	DefaultContainerStateRoot = "/var/lib/cyberpanel/containers/runtime"
	DefaultContainerRootlessUser = "cyberpanel-containers"
	containerRuntimeAdapterID = "container-runtime"
	containerRuntimeAdapterVersion = "1"
	containerCommandOutputLimit = 2 << 20
)

type LinuxContainerConfig struct {
	StateRoot string
	PodmanPath string
	SkopeoPath string
	RootlessUser string
	RootlessUID uint32
	RootlessGID uint32
	RootlessHome string
	Commands map[ID][]string
	Runner LinuxContainerCommandRunner
	Secrets *secrets.MaterialClient
}

func DefaultLinuxContainerConfig(material *secrets.MaterialClient)(LinuxContainerConfig,error){account,err:=user.Lookup(DefaultContainerRootlessUser);if err!=nil{return LinuxContainerConfig{},fmt.Errorf("resolve %s: %w",DefaultContainerRootlessUser,err)};uid,err:=strconv.ParseUint(account.Uid,10,32);if err!=nil||uid==0{return LinuxContainerConfig{},ErrForbidden};gid,err:=strconv.ParseUint(account.Gid,10,32);if err!=nil||gid==0{return LinuxContainerConfig{},ErrForbidden};commands:=map[ID][]string{"cmd_shell":{"/bin/sh"},"cmd_wp_cli":{"/usr/local/bin/wp"},"cmd_php":{"/usr/bin/php"},"cmd_composer":{"/usr/local/bin/composer"}};return LinuxContainerConfig{StateRoot:DefaultContainerStateRoot,PodmanPath:"/usr/bin/podman",SkopeoPath:"/usr/bin/skopeo",RootlessUser:DefaultContainerRootlessUser,RootlessUID:uint32(uid),RootlessGID:uint32(gid),RootlessHome:account.HomeDir,Commands:commands,Runner:NativeLinuxContainerCommandRunner{},Secrets:material},nil}

type LinuxContainerInvocation struct{Path string;Arguments []string;Environment []string;Input []byte;Directory string;UID,GID uint32;OutputLimit int}
type LinuxContainerCommandRunner interface{Run(context.Context,LinuxContainerInvocation)([]byte,int,error)}
type NativeLinuxContainerCommandRunner struct{}
func(NativeLinuxContainerCommandRunner)Run(ctx context.Context,invocation LinuxContainerInvocation)([]byte,int,error){if ctx==nil||(invocation.Path!="/usr/bin/podman"&&invocation.Path!="/usr/bin/skopeo")||invocation.OutputLimit<=0||invocation.OutputLimit>16<<20{return nil,-1,ErrInvalid};command:=exec.CommandContext(ctx,invocation.Path,invocation.Arguments...);command.Env=append([]string{"PATH=/usr/bin:/bin","LANG=C.UTF-8","LC_ALL=C.UTF-8"},invocation.Environment...);command.Dir=invocation.Directory;if command.Dir==""{command.Dir="/"};if invocation.UID!=0{command.SysProcAttr=&syscall.SysProcAttr{Credential:&syscall.Credential{Uid:invocation.UID,Gid:invocation.GID,NoSetGroups:true}}};if invocation.Input!=nil{command.Stdin=bytes.NewReader(invocation.Input)};output:=&limitedContainerOutput{limit:invocation.OutputLimit};command.Stdout=output;command.Stderr=output;err:=command.Run();exitCode:=0;if err!=nil{exitCode=-1;if value,ok:=err.(*exec.ExitError);ok{exitCode=value.ExitCode()}};if output.overflow{return output.Bytes(),exitCode,errors.Join(ErrAmbiguous,err)};if err!=nil{return output.Bytes(),exitCode,fmt.Errorf("container runtime operation failed: %w",err)};return output.Bytes(),exitCode,nil}

type limitedContainerOutput struct{buffer bytes.Buffer;limit int;overflow bool}
func(output *limitedContainerOutput)Write(content []byte)(int,error){original:=len(content);remaining:=output.limit-output.buffer.Len();if remaining>0{if len(content)>remaining{content=content[:remaining]};_,_=output.buffer.Write(content)};if original>remaining{output.overflow=true};return original,nil}
func(output *limitedContainerOutput)Bytes()[]byte{return append([]byte(nil),output.buffer.Bytes()...)}

type linuxRuntimeResource struct{TenantID ID `json:"tenant_id"`;ResourceID ID `json:"resource_id"`;RuntimeObjectID string `json:"runtime_object_id"`;Tier RuntimeTier `json:"tier"`;Generation uint64 `json:"generation"`;Fence FenceToken `json:"fence"`;SpecDigest string `json:"spec_digest,omitempty"`;Lifecycle Lifecycle `json:"lifecycle,omitempty"`;QuotaBytes uint64 `json:"quota_bytes,omitempty"`;InodeLimit uint64 `json:"inode_limit,omitempty"`;Ports []string `json:"ports,omitempty"`;UpdatedAt time.Time `json:"updated_at"`}
type linuxContainerState struct{Generation uint64 `json:"generation"`;Workloads map[ID]linuxRuntimeResource `json:"workloads"`;Volumes map[ID]linuxRuntimeResource `json:"volumes"`;Networks map[ID]linuxRuntimeResource `json:"networks"`;Exposures map[ID]linuxRuntimeResource `json:"exposures"`}

type LinuxContainerRuntime struct{config LinuxContainerConfig;mu sync.Mutex;state linuxContainerState;statePath string;clock func()time.Time}
func NewLinuxContainerRuntime(config LinuxContainerConfig)(*LinuxContainerRuntime,error){if !filepath.IsAbs(config.StateRoot)||config.PodmanPath!="/usr/bin/podman"||config.SkopeoPath!="/usr/bin/skopeo"||config.RootlessUID==0||config.RootlessGID==0||config.RootlessHome==""||config.Runner==nil||config.Secrets==nil{return nil,ErrInvalid};if err:=ensureContainerDirectory(config.StateRoot,0o710,0,int(config.RootlessGID));err!=nil{return nil,err};runtimeDirectory:="/run/user/"+strconv.FormatUint(uint64(config.RootlessUID),10);if err:=ensureContainerDirectory(runtimeDirectory,0o700,int(config.RootlessUID),int(config.RootlessGID));err!=nil{return nil,err};runtime:=&LinuxContainerRuntime{config:config,statePath:filepath.Join(config.StateRoot,"state.json"),clock:time.Now};runtime.state=linuxContainerState{Generation:1,Workloads:map[ID]linuxRuntimeResource{},Volumes:map[ID]linuxRuntimeResource{},Networks:map[ID]linuxRuntimeResource{},Exposures:map[ID]linuxRuntimeResource{}};if content,err:=readBoundedContainerFile(runtime.statePath,16<<20);err==nil{if json.Unmarshal(content,&runtime.state)!=nil{return nil,ErrInvalid};runtime.normalizeState()}else if !errors.Is(err,os.ErrNotExist){return nil,err};return runtime,nil}
func(runtime *LinuxContainerRuntime)normalizeState(){if runtime.state.Generation==0{runtime.state.Generation=1};if runtime.state.Workloads==nil{runtime.state.Workloads=map[ID]linuxRuntimeResource{}};if runtime.state.Volumes==nil{runtime.state.Volumes=map[ID]linuxRuntimeResource{}};if runtime.state.Networks==nil{runtime.state.Networks=map[ID]linuxRuntimeResource{}};if runtime.state.Exposures==nil{runtime.state.Exposures=map[ID]linuxRuntimeResource{}}}
func(runtime *LinuxContainerRuntime)saveLocked()error{runtime.state.Generation++;content,err:=json.Marshal(runtime.state);if err!=nil{return err};return atomicContainerFile(runtime.statePath,content,0o600)}

func(runtime *LinuxContainerRuntime)InspectRuntime(ctx context.Context)(RuntimeCapability,error){output,_,err:=runtime.run(ctx,TierTenantRootless,runtime.config.PodmanPath,[]string{"info","--format","json"},nil);runtime.mu.Lock();generation:=runtime.state.Generation;runtime.mu.Unlock();capability:=RuntimeCapability{Backend:"podman",Generation:generation};if err!=nil{return capability,err};var value struct{Version struct{Version string `json:"Version"`;APIVersion string `json:"APIVersion"`} `json:"version"`;Host struct{CgroupVersion string `json:"cgroupVersion"`;Security struct{Rootless bool `json:"rootless"`;SeccompEnabled bool `json:"seccompEnabled"`;AppArmorEnabled bool `json:"apparmorEnabled"`;SELinuxEnabled bool `json:"selinuxEnabled"`} `json:"security"`;IDMappings struct{UIDMap []json.RawMessage `json:"uidmap"`;GIDMap []json.RawMessage `json:"gidmap"`} `json:"idMappings"`} `json:"host"`};if json.Unmarshal(output,&value)!=nil{return capability,ErrInvalid};capability.Version=value.Version.Version;capability.APIVersion=value.Version.APIVersion;capability.Rootless=value.Host.Security.Rootless;capability.UserNamespaces=len(value.Host.IDMappings.UIDMap)>0&&len(value.Host.IDMappings.GIDMap)>0;capability.CgroupV2=value.Host.CgroupVersion=="v2";capability.Seccomp=value.Host.Security.SeccompEnabled;capability.MAC=value.Host.Security.AppArmorEnabled||value.Host.Security.SELinuxEnabled;return capability,nil}
func(runtime *LinuxContainerRuntime)InstallRuntime(ctx context.Context,request RuntimeInstallRequest)(RuntimeReceipt,error){if request.EffectID==""||!request.ProfileID.Valid()||!validContainerSHA256(request.ArtifactDigest)||!validContainerSHA256(request.RepositorySnapshotDigest)||len(request.CommitAuthorizationDigest)!=64||request.Fence==0{return RuntimeReceipt{},ErrInvalid};capability,err:=runtime.InspectRuntime(ctx);receipt:=RuntimeReceipt{EffectID:request.EffectID,ResourceID:request.ProfileID,RuntimeObjectID:capability.Backend,ObservedDigest:digestContainerValue(capability),Fence:request.Fence,Outcome:"confirmed",ObservedAt:runtime.clock().UTC()};if err!=nil{receipt.Outcome="rejected";receipt.ErrorCode="RUNTIME_NOT_INSTALLED";return receipt,ErrPolicy};return receipt,nil}
func(runtime *LinuxContainerRuntime)RemoveRuntime(_ context.Context,request RuntimeMutationRequest)(RuntimeReceipt,error){receipt:=RuntimeReceipt{EffectID:request.EffectID,Outcome:"rejected",ErrorCode:"RUNTIME_MANAGED_BY_INSTALLER",ObservedAt:runtime.clock().UTC(),Fence:request.Fence};return receipt,ErrPolicy}

func(runtime *LinuxContainerRuntime)ResolveImage(_ context.Context,_ ResolveImageRequest)(ImageReference,error){return ImageReference{},fmt.Errorf("%w: remote image resolution disabled",ErrPolicy)}

func(runtime *LinuxContainerRuntime)PullImage(_ context.Context,request PullImageRequest)(PullReceipt,error){return PullReceipt{EffectID:request.EffectID,ImageDigest:request.Image.Digest,Policy:request.Policy,Outcome:"rejected",ObservedAt:runtime.clock().UTC()},fmt.Errorf("%w: remote image pulls disabled",ErrPolicy)}
func(runtime *LinuxContainerRuntime)DeleteImage(ctx context.Context,request ImageMutationRequest)(PullReceipt,error){receipt:=PullReceipt{EffectID:request.EffectID,ImageDigest:request.ImageDigest,ObservedAt:runtime.clock().UTC()};if request.EffectID==""||request.Fence==0||!validContainerSHA256(request.ImageDigest)||grantFor(request.Grant,"image.delete",request.Grant.ResourceID,runtime.clock().UTC())!=nil{return receipt,ErrInvalid};_,_,err:=runtime.run(ctx,TierTenantRootless,runtime.config.PodmanPath,[]string{"image","rm","--",request.ImageDigest},nil);if err!=nil{return receipt,err};receipt.Outcome="confirmed";return receipt,nil}

