func(runtime *LinuxContainerRuntime)DeleteVolume(ctx context.Context,request VolumeMutationRequest)(VolumeReceipt,error){receipt:=VolumeReceipt{EffectID:request.EffectID,VolumeID:request.VolumeID,Fence:request.Fence,ObservedAt:runtime.clock().UTC()};if request.EffectID==""||request.Fence==0||grantFor(request.Grant,"volume.delete",request.VolumeID,runtime.clock().UTC())!=nil{return failVolumeReceipt(receipt,ErrForbidden)};runtime.mu.Lock();defer runtime.mu.Unlock();record,ok:=runtime.state.Volumes[request.VolumeID];if !ok{return failVolumeReceipt(receipt,ErrNotFound)};receipt.QuotaBytes=record.QuotaBytes;receipt.InodeLimit=record.InodeLimit;if record.TenantID!=request.Grant.TenantID||record.Tier!=TierTenantRootless||record.Generation!=request.ExpectedGeneration||record.Fence>request.Fence{return failVolumeReceipt(receipt,ErrStale)};if err:=runtime.inspectManagedVolume(ctx,record);err!=nil{return failVolumeReceipt(receipt,err)};if _,_,err:=runtime.run(ctx,TierTenantRootless,runtime.config.PodmanPath,[]string{"volume","rm","--",record.RuntimeObjectID},nil);err!=nil{return failVolumeReceipt(receipt,ErrInUse)};delete(runtime.state.Volumes,request.VolumeID);if err:=runtime.saveLocked();err!=nil{return failVolumeReceipt(receipt,errors.Join(ErrAmbiguous,err))};receipt.RuntimeObjectID=record.RuntimeObjectID;receipt.ConfigurationDigest=record.SpecDigest;receipt.Generation=record.Generation+1;receipt.Outcome="confirmed";return receipt,nil}

