func(runtime *LinuxContainerRuntime)ObserveWorkload(ctx context.Context,request WorkloadObservationRequest)(RuntimeReceipt,error){receipt:=RuntimeReceipt{ResourceID:request.WorkloadID,ObservedAt:runtime.clock().UTC(),Health:HealthUnknown};if grantFor(request.Grant,"workload.reconcile",request.WorkloadID,runtime.clock().UTC())!=nil{return failRuntimeReceipt(receipt,ErrForbidden)};runtime.mu.Lock();record,ok:=runtime.state.Workloads[request.WorkloadID];runtime.mu.Unlock();if !ok{return failRuntimeReceipt(receipt,ErrNotFound)};if record.TenantID!=request.Grant.TenantID||record.Generation!=request.ExpectedGeneration{return failRuntimeReceipt(receipt,ErrStale)};lifecycle,observed,_,health,err:=runtime.inspectWorkload(ctx,record);if err!=nil{return failRuntimeReceipt(receipt,err)};receipt.RuntimeObjectID=record.RuntimeObjectID;receipt.SpecDigest=record.SpecDigest;receipt.ObservedDigest=observed;receipt.Lifecycle=lifecycle;receipt.Health=health;receipt.Generation=record.Generation;receipt.Fence=record.Fence;receipt.Outcome="confirmed";return receipt,nil}
