func failRuntimeReceipt(receipt RuntimeReceipt,err error)(RuntimeReceipt,error){receipt.Outcome="rejected";if errors.Is(err,ErrAmbiguous){receipt.Outcome="ambiguous"};return receipt,err}
func(runtime *LinuxContainerRuntime)run(ctx context.Context,tier RuntimeTier,path string,arguments []string,input []byte)([]byte,int,error){return runtime.runLimit(ctx,tier,path,arguments,input,containerCommandOutputLimit)}
func(runtime *LinuxContainerRuntime)runLimit(ctx context.Context,tier RuntimeTier,path string,arguments []string,input []byte,limit int)([]byte,int,error){invocation:=LinuxContainerInvocation{Path:path,Arguments:append([]string(nil),arguments...),Input:input,OutputLimit:limit};if tier==TierTenantRootless{invocation.UID=runtime.config.RootlessUID;invocation.GID=runtime.config.RootlessGID;invocation.Directory=runtime.config.RootlessHome;invocation.Environment=[]string{"HOME="+runtime.config.RootlessHome,"USER="+runtime.config.RootlessUser,"LOGNAME="+runtime.config.RootlessUser,"XDG_RUNTIME_DIR=/run/user/"+strconv.FormatUint(uint64(runtime.config.RootlessUID),10)}};return runtime.config.Runner.Run(ctx,invocation)}

func volumeConfigurationDigest(request VolumeMutationRequest)string{return digestContainerValue(struct{Tenant,Volume ID;Tier RuntimeTier;Class string;QuotaBytes,InodeLimit uint64}{request.Grant.TenantID,request.VolumeID,request.Tier,request.Class,request.QuotaBytes,request.InodeLimit})}
func networkConfigurationDigest(request NetworkMutationRequest)string{return digestContainerValue(struct{Tenant,Network ID;Tier RuntimeTier;IPv4,IPv6 netip.Prefix;Internal bool;DNSPolicy string}{request.Grant.TenantID,request.NetworkID,request.Tier,request.IPv4,request.IPv6,request.Internal,request.DNSPolicy})}
func exposureConfigurationDigest(exposure Exposure)string{return digestContainerValue(struct{Tenant,Exposure,Workload ID;PortName string;Public bool;Listener,Domain string;CIDRs []netip.Prefix}{exposure.TenantID,exposure.ID,exposure.WorkloadID,exposure.PortName,exposure.Public,exposure.ListenerRef,exposure.DomainBindingRef,prefixesSorted(exposure.AllowedCIDRs)})}
func(runtime *LinuxContainerRuntime)inspectManagedVolume(ctx context.Context,record linuxRuntimeResource)error{output,_,err:=runtime.run(ctx,TierTenantRootless,runtime.config.PodmanPath,[]string{"volume","inspect","--format","json","--",record.RuntimeObjectID},nil);if err!=nil{return errors.Join(ErrNotFound,err)};var rows []struct{Name,Mountpoint string;Labels map[string]string};if json.Unmarshal(output,&rows)!=nil||len(rows)!=1||rows[0].Name!=record.RuntimeObjectID{return ErrInvalid};labels:=rows[0].Labels;if labels["io.cyberpanel.tenant"]!=record.TenantID.String()||labels["io.cyberpanel.resource"]!=record.ResourceID.String()||labels["io.cyberpanel.owner-uid"]!=strconv.FormatUint(uint64(runtime.config.RootlessUID),10)||labels["io.cyberpanel.config"]!=record.SpecDigest{return ErrForbidden};root,err:=filepath.EvalSymlinks(filepath.Join(runtime.config.RootlessHome,".local","share","containers","storage","volumes"));if err!=nil{return ErrForbidden};mountpoint,err:=filepath.EvalSymlinks(rows[0].Mountpoint);if err!=nil{return ErrForbidden};relative,err:=filepath.Rel(root,mountpoint);if err!=nil||relative=="."||relative==".."||strings.HasPrefix(relative,".."+string(os.PathSeparator)){return ErrForbidden};info,err:=os.Lstat(mountpoint);if err!=nil||!info.IsDir()||info.Mode()&os.ModeSymlink!=0{return ErrForbidden};stat,ok:=info.Sys().(*syscall.Stat_t);if !ok||stat.Uid!=runtime.config.RootlessUID||stat.Gid!=runtime.config.RootlessGID{return ErrForbidden};return nil}
