func(runtime *LinuxContainerRuntime)inspectPrivateNetworkRecord(ctx context.Context,record linuxRuntimeResource)error{return runtime.inspectPrivateNetwork(ctx,record,NetworkMutationRequest{})}
func(runtime *LinuxContainerRuntime)observeLoopbackExposure(ctx context.Context,workload linuxRuntimeResource,portName string)(string,uint16,error){port:=LoopbackExposurePort(workload.ResourceID,portName);output,_,err:=runtime.run(ctx,TierTenantRootless,runtime.config.PodmanPath,[]string{"port","--",workload.RuntimeObjectID},nil);if err!=nil{return "",0,err};expected:="127.0.0.1:"+strconv.FormatUint(uint64(port),10);for _,line:=range strings.Split(string(output),"\n"){parts:=strings.SplitN(strings.TrimSpace(line)," -> ",2);if len(parts)==2&&parts[1]==expected{return "127.0.0.1",port,nil}};return "",0,ErrNotFound}
func failVolumeReceipt(receipt VolumeReceipt,err error)(VolumeReceipt,error){receipt.Outcome="rejected";if errors.Is(err,ErrAmbiguous){receipt.Outcome="ambiguous"};return receipt,err}
func failNetworkReceipt(receipt NetworkReceipt,err error)(NetworkReceipt,error){receipt.Outcome="rejected";if errors.Is(err,ErrAmbiguous){receipt.Outcome="ambiguous"};return receipt,err}
