func runtimeName(prefix string,tenant,resource ID)string{sum:=sha256.Sum256([]byte(prefix+"\x00"+tenant.String()+"\x00"+resource.String()));return prefix+"-"+hex.EncodeToString(sum[:12])}
func LoopbackExposurePort(workload ID,portName string)uint16{sum:=sha256.Sum256([]byte("cyberpanel:container-loopback-port:v1\x00"+workload.String()+"\x00"+portName));value:=uint16(sum[0])<<8|uint16(sum[1]);return 20000+value%40000}
func volumeTier(class string)RuntimeTier{if class=="admin_rootful"{return TierAdminRootful};return TierTenantRootless}
func validContainerSHA256(value string)bool{if len(value)!=71||!strings.HasPrefix(value,"sha256:"){return false};_,err:=hex.DecodeString(value[7:]);return err==nil}
func digestContainerValue(value any)string{encoded,_:=json.Marshal(value);sum:=sha256.Sum256(encoded);return hex.EncodeToString(sum[:])}
func grantFor(grant Grant,operation string,resource ID,now time.Time)error{if !grant.TenantID.Valid()||grant.ResourceID!=resource||grant.Operation!=operation||grant.AuthzEpoch==0||!now.Before(grant.ExpiresAt)||len(grant.Digest)!=64{return ErrForbidden};return nil}
func validRegistryName(value string)bool{return value!=""&&!strings.ContainsAny(value,"/@ \t\r\n")&&!strings.HasPrefix(value,".")}
func validRepositoryName(value string)bool{return strings.Trim(value,"/")!=""&&!strings.ContainsAny(value,"@ \t\r\n")&&!strings.Contains(value,"..")}
func validDNSPolicy(value string)bool{return value=="managed"||value=="tenant"||value=="disabled"||value=="internal"}
func validContainerAlias(value string)bool{return value!=""&&len(value)<=63&&!strings.ContainsAny(value,"/@: \t\r\n")&&!strings.HasPrefix(value,"-")&&!strings.HasSuffix(value,"-")}
func exposurePortAllowed(exposure Exposure,workload ID)bool{return exposure.WorkloadID==workload&&exposure.PortName!=""&&(!exposure.Public||exposure.ListenerRef!=""&&exposure.DomainBindingRef!="")}
func containerPortOutputContains(output []byte,port uint16)bool{needle:=":"+strconv.FormatUint(uint64(port),10);for _,line:=range strings.Split(string(output),"\n"){line=strings.TrimSpace(line);if strings.HasSuffix(line,needle)||strings.Contains(line,needle+" "){return true}};return false}
func formatCPUQuota(quota,period uint64)string{if quota==0||period==0{return "1.000"};return strconv.FormatFloat(float64(quota)/float64(period),'f',3,64)}
func podmanRestart(value RestartPolicy)string{switch value{case RestartOnFailure:return "on-failure";case RestartUnlessStopped:return "unless-stopped";default:return "no"}}
func parseContainerBytes(value string)uint64{first:=strings.TrimSpace(strings.Split(value,"/")[0]);fields:=strings.Fields(first);if len(fields)==0{return 0};number,err:=strconv.ParseFloat(fields[0],64);if err!=nil{return 0};unit:="B";if len(fields)>1{unit=fields[1]}else{for index,ch:=range fields[0]{if ch<'0'||ch>'9'&&ch!='.'{number,_=strconv.ParseFloat(fields[0][:index],64);unit=fields[0][index:];break}}};multipliers:=map[string]float64{"B":1,"kB":1e3,"KB":1e3,"KiB":1024,"MB":1e6,"MiB":1<<20,"GB":1e9,"GiB":1<<30};return uint64(number*multipliers[unit])}
func wipeContainer(content []byte){for index:=range content{content[index]=0}}
func prefixesSorted(values []netip.Prefix)[]netip.Prefix{out:=append([]netip.Prefix(nil),values...);sort.Slice(out,func(i,j int)bool{return out[i].String()<out[j].String()});return out}

var _ Broker=(*LinuxContainerRuntime)(nil)
